# Example frontend

Synthetic ticket-card library. No browser or installed dependencies are needed.
Run `npm test` for the existing smoke checks.

`src/cards.mjs` owns card presentation. New card builders follow the two
existing builders: use the shared title normalizer and frozen card factory;
preserve their input errors, key shape and immutable results.
`src/priority.mjs` consumes the API's `priority` wire field. The API repository
owns the response contract; do not duplicate its schema here.
{
  "name": "example-frontend",
  "private": true,
  "type": "module",
  "scripts": { "test": "node checks.mjs" }
}
export function priorityLabel(ticket) {
  return ticket.priority === "high" ? "High priority" : "Normal priority";
}
function normalizeTitle(title) {
  if (typeof title !== "string") throw new TypeError("title must be a string");
  return title.trim().replace(/\s+/g, " ");
}

function makeCard(state, title) {
  return Object.freeze({ state, title: normalizeTitle(title) });
}

export function activeCard(title) {
  return makeCard("active", title);
}

export function queuedCard(title) {
  return makeCard("queued", title);
}
import assert from "node:assert/strict";
import { activeCard, queuedCard } from "./src/cards.mjs";
import { priorityLabel } from "./src/priority.mjs";

assert.deepEqual(activeCard("  A   title "), { state: "active", title: "A title" });
assert.equal(Object.isFrozen(queuedCard("Queue")), true);
assert.throws(() => activeCard(null), TypeError);
assert.equal(priorityLabel({ priority: "high" }), "High priority");
console.log("frontend smoke: passed");
